def __init__(self, engine, opts, now):
    self.engine, self.opts, self.now = engine, opts, now
    self.stats = dict(total=0, normal=0, disabled=0, in_cooldown=0, no_cooldown=0,
                      **empty_quota_stats())
    if engine in ('sqlite', 'postgres'):
        self.stats['permanent_disabled'] = 0
    self.families = {f: dict(supported=0, unavailable=0, unknown=0) for f in FAMILIES}
    self.base_total = self.total = 0
    self.page = []

def add(self, raw, classification=None):
    o, stats = self.opts, self.stats
    row = _project(raw, self.now)
    disabled, permanent = raw['disabled'], raw['permanent_disabled']
    stats['total'] += 1
    if 'permanent_disabled' in stats and permanent:
        stats['permanent_disabled'] += 1
    elif disabled:
        stats['disabled'] += 1
    else:
        stats['normal'] += 1
    normal = not disabled and (not permanent or self.engine in ('mysql', 'mongo'))
    if normal:
        stats['in_cooldown' if has_active_model_cooldown(raw.get('model_cooldowns'), self.now) else 'no_cooldown'] += 1
        if self.engine != 'mongo' or not permanent:
            count_quota_summary(stats, row)
    # Preserve each engine's original query scope for expiry observation.
    # Mongo applies its raw error-code condition before reading candidates.
    status = o['status_filter']
    if self.engine in ('mysql', 'mongo'):
        status_ok = status not in ('enabled', 'disabled') or disabled == (status == 'disabled')
    else:
        status_ok = (status == 'all' or status == 'enabled' and not disabled and not permanent
                     or status == 'disabled' and disabled and not permanent
                     or status == 'permanent_disabled' and permanent)
    ef = o['error_code_filter']
    raw_error_ok = (has_error_code(row['error_codes'], 403)
                    if is_http_403_classification_filter(ef)
                    else matches_error_code_filter(row['error_codes'], {}, ef))
    if self.engine == 'sqlite' or status_ok and (self.engine != 'mongo' or raw_error_ok):
        observe_quota_expiry(stats, row)
    if not status_ok:
        return
    if is_http_403_classification_filter(ef):
        if not matches_http_403_classification(classification or {}, ef):
            return
    elif not matches_error_code_filter(row['error_codes'], {}, ef):
        return
    if o['tier_filter'] not in (None, '', 'all') and row['tier'] != o['tier_filter']:
        return
    if o['remark_filter'] is not None and row['remark'] != o['remark_filter']:
        return
    cd = o['cooldown_filter']
    if cd in GROUP_FILTERS and not matches_quota_filter(row, cd):
        return
    if cd == 'in_cooldown' and not row['model_cooldowns']:
        return
    if cd == 'no_cooldown' and row['model_cooldowns']:
        return
    if cd in ('pro_no_cooldown', 'flash_no_cooldown') and cooldowns_affect_antigravity_family(row['model_cooldowns'], cd.split('_')[0]):
        return
    if not matches_credential_search(row['filename'], row.get('user_email'), o.get('search')):
        return
    self.base_total += 1
    statuses = {family: _status(row['model_access_families'].get(family, {}), self.now)
                for family in FAMILIES}
    for family in FAMILIES:
        self.families[family][statuses[family]] += 1
    if o['model_access_filter'] != 'all' and statuses[o['model_access_family']] != o['model_access_filter']:
        return
    if o['offset'] <= self.total < o['offset'] + o['limit']:
        if classification is not None:
            row['error_classifications'] = classification
        self.page.append(row)
    self.total += 1

def result(self):
    return dict(items=self.page, total=self.total, offset=self.opts['offset'], limit=self.opts['limit'],
                stats=self.stats, quota_group_filter_supported=True,
                model_access_summary={'total': self.base_total, 'family_counts': self.families,

global_stats = {
    "total": 0,
    "normal": 0,
    "disabled": 0,
    "permanent_disabled": 0,
    "in_cooldown": 0,
    "no_cooldown": 0,
}
async with db.execute(
    f"SELECT disabled, permanent_disabled, COUNT(*) "
    f"FROM {table_name} GROUP BY disabled, permanent_disabled"
) as stats_cursor:
    for disabled, permanent_disabled, count in await stats_cursor.fetchall():
        global_stats["total"] += count
        if permanent_disabled:
            global_stats["permanent_disabled"] += count
        elif disabled:
            global_stats["disabled"] += count
        else:
            global_stats["normal"] += count

if mode == "antigravity":
    global_stats.update(empty_quota_stats())
cooldown_columns = "model_cooldowns, quota_group_states, disabled, permanent_disabled" if mode == "antigravity" else "model_cooldowns"
cooldown_where = "" if mode == "antigravity" else (
    "WHERE COALESCE(disabled, 0) = 0 AND COALESCE(permanent_disabled, 0) = 0"
)
async with db.execute(
    f"SELECT {cooldown_columns} FROM {table_name} {cooldown_where}"
) as cooldown_cursor:
    async for cooldown_row in cooldown_cursor:
        model_cooldowns = cooldown_row[0]
        if mode == "antigravity":
            group_summary = quota_summary(model_cooldowns, cooldown_row[1], current_time)
            observe_quota_expiry(global_stats, group_summary)
            if cooldown_row[2] or cooldown_row[3]:
                continue
        active, invalid = active_model_cooldowns(
            model_cooldowns, current_time
        )
        invalid_cooldown_count += invalid
        global_stats[
            "in_cooldown" if active else "no_cooldown"
        ] += 1
        if mode == "antigravity":
            count_quota_summary(global_stats, group_summary)

if has_value_filters or status_filter not in {None, "all"}:
    async with db.execute(
        f"SELECT COUNT(*) FROM {table_name} {where_clause}", params
    ) as count_cursor:
        count_row = await count_cursor.fetchone()
    total_count = int(count_row[0]) if count_row else 0
else:
    total_count = global_stats["total"]

if mode == "geminicli":
    page_query = f"""
        SELECT filename, disabled, error_codes, last_success,
               user_email, rotation_order, model_cooldowns, preview, tier,
               success_count, failure_count, permanent_disabled, cycle_stats, last_cycle_stats, remark,
               tier_raw_id, tier_raw_name, tier_detected_at,
               health_status, quarantine_reason, probe_stage, next_probe_at,
               last_health_check_at, health_check_started_at, health_state_version

def empty_quota_stats():
    return {key: 0 for key in ("quota_restricted", "quota_unrestricted", "quota_blocked_unknown", "quota_state_invalid", "quota_next_expiry")}


def observe_quota_expiry(stats, summary):
    """Earliest upcoming group expiry, including candidates excluded by a filter."""
    deadlines = [state["cooldownUntil"] for state in summary["quota_groups"].values() if state["cooldownUntil"] > 0]
    if deadlines:
        stats["quota_next_expiry"] = min(deadlines + ([stats["quota_next_expiry"]] if stats["quota_next_expiry"] else []))


def count_quota_summary(stats, summary):
    """Count once per enabled credential, independently of list filters."""
    stats["quota_restricted" if matches_quota_filter(summary, "any_restricted") else "quota_unrestricted"] += 1
    stats["quota_blocked_unknown"] += int(any(group["blockedUnknown"] for group in summary["quota_groups"].values()))
    stats["quota_state_invalid"] += int(summary["quota_state_invalid"])
    observe_quota_expiry(stats, summary)
